function intenzitet(v, p) {
  const x = v * p;
  if (x <= 2) return { x, nivo: 'Nizak', prioritet: 'Niski prioritet' };
  if (x <= 4) return { x, nivo: 'Srednji', prioritet: 'Umjereni prioritet' };
  return { x, nivo: 'Visok', prioritet: 'Visoki prioritet' };
}

module.exports = { OBLASTI, R, intenzitet };
